CREATE PROCEDURE [purchase].[Purchase_Return] @PurchaseInvoiceId UNIQUEIDENTIFIER,@ItemsJson NVARCHAR(MAX),@Reason NVARCHAR(250),@CreatedBy NVARCHAR(256)=NULL AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF ISJSON(@ItemsJson)<>1 THROW 51200,'Return items are required.',1;DECLARE @Warehouse UNIQUEIDENTIFIER,@Tx UNIQUEIDENTIFIER=NEWID(),@ReturnNo NVARCHAR(50)=CONCAT('PRET-',UPPER(LEFT(REPLACE(CONVERT(NVARCHAR(36),NEWID()),'-',''),18))),@Adjustment DECIMAL(18,2)=0;SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;BEGIN TRAN;SELECT @Warehouse=WarehouseId FROM purchase.PurchaseInvoices WITH(UPDLOCK)WHERE PurchaseInvoiceId=@PurchaseInvoiceId AND Status IN('POSTED','PARTIALLY_RETURNED');IF @Warehouse IS NULL BEGIN ROLLBACK;THROW 51200,'Purchase is not returnable.',1;END;INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy)VALUES(@Tx,@ReturnNo+'-STK','RETURN','PURCHASE_RETURN',@PurchaseInvoiceId,@Warehouse,@Reason,@CreatedBy);DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT PurchaseItemId,Quantity FROM OPENJSON(@ItemsJson)WITH(PurchaseItemId UNIQUEIDENTIFIER,Quantity DECIMAL(18,4));DECLARE @Item UNIQUEIDENTIFIER,@Qty DECIMAL(18,4),@Product UNIQUEIDENTIFIER,@Batch NVARCHAR(100),@Purchased DECIMAL(18,4),@Returned DECIMAL(18,4),@Free DECIMAL(18,4),@Line DECIMAL(18,2),@Balance UNIQUEIDENTIFIER,@Available DECIMAL(18,4),@Cost DECIMAL(18,4);OPEN c;FETCH NEXT FROM c INTO @Item,@Qty;WHILE @@FETCH_STATUS=0 BEGIN SELECT @Product=ProductId,@Batch=BatchNo,@Purchased=Quantity,@Free=FreeQuantity,@Returned=ReturnedQuantity,@Line=LineTotal FROM purchase.PurchaseInvoiceItems WITH(UPDLOCK)WHERE PurchaseItemId=@Item AND PurchaseInvoiceId=@PurchaseInvoiceId;IF @Product IS NULL OR @Qty<=0 OR @Returned+@Qty>@Purchased+@Free BEGIN CLOSE c;DEALLOCATE c;ROLLBACK;THROW 51200,'Invalid return quantity.',1;END;SELECT @Balance=InventoryBalanceId,@Available=QuantityAvailable,@Cost=AverageCost FROM inventory.InventoryBalances WITH(UPDLOCK,HOLDLOCK)WHERE ProductId=@Product AND WarehouseId=@Warehouse AND ZoneId IS NULL AND BinId IS NULL AND ISNULL(BatchNo,'')=ISNULL(@Batch,'') AND SerialNo IS NULL;IF @Balance IS NULL OR @Available<@Qty BEGIN CLOSE c;DEALLOCATE c;ROLLBACK;THROW 51201,'Insufficient stock for purchase return.',1;END;UPDATE inventory.InventoryBalances SET QuantityOnHand=QuantityOnHand-@Qty,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE InventoryBalanceId=@Balance;UPDATE purchase.PurchaseInvoiceItems SET ReturnedQuantity=ReturnedQuantity+@Qty WHERE PurchaseItemId=@Item;DECLARE @Amount DECIMAL(18,2)=ROUND(@Line/NULLIF(@Purchased+@Free,0)*@Qty,2);SET @Adjustment+=@Amount;INSERT purchase.PurchaseReturns(ReturnNumber,PurchaseInvoiceId,PurchaseItemId,Quantity,AdjustmentAmount,Reason,CreatedBy)VALUES(CONCAT(@ReturnNo,'-',RIGHT(CONVERT(NVARCHAR(36),@Item),4)),@PurchaseInvoiceId,@Item,@Qty,@Amount,@Reason,@CreatedBy);INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,BatchNo,Quantity,UnitCost)VALUES(@Tx,@Product,@Batch,@Qty,@Cost);INSERT inventory.InventoryValuation(ProductId,WarehouseId,ValuationMethod,Quantity,UnitCost)SELECT @Product,@Warehouse,'AVERAGE',QuantityOnHand,AverageCost FROM inventory.InventoryBalances WHERE InventoryBalanceId=@Balance;FETCH NEXT FROM c INTO @Item,@Qty;END;CLOSE c;DEALLOCATE c;UPDATE purchase.PurchaseInvoices SET Status=CASE WHEN NOT EXISTS(SELECT 1 FROM purchase.PurchaseInvoiceItems WHERE PurchaseInvoiceId=@PurchaseInvoiceId AND ReturnedQuantity<Quantity+FreeQuantity)THEN'RETURNED'ELSE'PARTIALLY_RETURNED'END,ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE PurchaseInvoiceId=@PurchaseInvoiceId;COMMIT;SELECT @PurchaseInvoiceId PurchaseInvoiceId,@ReturnNo ReturnNumber,@Adjustment AdjustmentAmount,@Tx TransactionId;END;
